<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?= esc($title) ?></title><script src="https://cdn.tailwindcss.com"></script>
    <script>tailwind.config={theme:{extend:{colors: { rescue: { 50: '#EFF8FC', 100: '#D4EDF7', 200: '#A9DBEF', 300: '#6DC3E3', 400: '#30A8D2', 500: '#0D7EA3', 600: '#0A6A8A', 700: '#085670', 800: '#064257', 900: '#03293A' }, catgold: { 50: '#FFFBEB', 100: '#FEF3C7', 200: '#FDE68A', 300: '#FCD34D', 400: '#FBBF24', 500: '#F59E0B', 600: '#D97706', 700: '#B45309', 800: '#92400E', 900: '#78350F' }, adopted: { 50: '#F0FDF4', 100: '#DCFCE7', 200: '#BBF7D0', 300: '#86EFAC', 400: '#4ADE80', 500: '#22C55E', 600: '#16A34A', 700: '#15803D', 800: '#166534', 900: '#14532D' }, wanted: { 50: '#FEF2F2', 100: '#FEE2E2', 200: '#FECACA', 300: '#FCA5A5', 400: '#F87171', 500: '#EF4444', 600: '#DC2626', 700: '#B91C1C', 800: '#991B1B', 900: '#7F1D1D' }, foster: { 50: '#FAF5FF', 100: '#F3E8FF', 200: '#E9D5FF', 300: '#D8B4FE', 400: '#C084FC', 500: '#A855F7', 600: '#9333EA', 700: '#7E22CE', 800: '#6B21A8', 900: '#581C87' } }}}}</script><script defer src="https://unpkg.com/alpinejs@3.x.x/dist/cdn.min.js"></script><script src="https://unpkg.com/lucide@latest"></script><link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&display=swap" rel="stylesheet"><style>body{font-family:Inter,sans-serif}[x-cloak]{display:none!important}</style></head><body class="bg-slate-50"><header class="border-b bg-white"><div class="mx-auto flex max-w-5xl items-center justify-between px-5 py-4"><a href="<?= site_url('/') ?>" class="flex items-center gap-3 font-bold"><span class="flex h-10 w-10 items-center justify-center rounded-xl bg-rescue-600 text-white"><i data-lucide="paw-print"></i></span>CatCare 360</a><a href="<?= site_url('volunteer/login') ?>" class="text-sm font-semibold text-rescue-600">Volunteer Sign In</a></div></header><?php if(session('applicant_name')): ?><main class="mx-auto max-w-xl px-5 py-20 text-center"><div class="rounded-3xl bg-white p-10 shadow-sm"><i data-lucide="circle-check-big" class="mx-auto h-16 w-16 text-adopted-500"></i><h1 class="mt-5 text-3xl font-bold">Application received!</h1><p class="mt-3 text-slate-600">Thanks, <?= esc(session('applicant_name')) ?>. The shelter team will review your volunteer application and contact you using the email you provided.</p><a href="<?= site_url('/') ?>" class="mt-7 inline-flex rounded-xl bg-rescue-600 px-5 py-3 text-sm font-semibold text-white">Back to CatCare 360</a></div></main><?php else: ?><main class="mx-auto max-w-3xl px-5 py-10" x-data="{step:1, days:[], roles:[], canNext(){return true}}"><div class="mb-8 text-center"><p class="text-sm font-bold uppercase tracking-widest text-rescue-600">McKinley West Cats</p><h1 class="mt-2 text-3xl font-bold">Volunteer Application</h1><p class="mt-2 text-slate-500">Help us provide consistent, compassionate care to shelter cats.</p></div><?php if(session('error')): ?><div class="mb-5 rounded-xl border border-red-200 bg-red-50 p-4 text-sm text-red-700"><?= esc(session('error')) ?></div><?php endif; ?><div class="mb-7 flex justify-between gap-2"><?php foreach(['Personal Info','Availability','Experience','Final Step'] as $i=>$name): ?><div class="flex-1 text-center"><span class="mx-auto flex h-8 w-8 items-center justify-center rounded-full text-sm font-bold" :class="step>=<?= $i+1 ?>?'bg-rescue-600 text-white':'bg-slate-200 text-slate-500'"><?= $i+1 ?></span><small class="mt-1 block text-xs text-slate-500"><?= $name ?></small></div><?php endforeach; ?></div><form method="post" class="overflow-hidden rounded-2xl border bg-white shadow-sm"><?= csrf_field() ?><div class="min-h-[390px] p-6 sm:p-8"><section x-show="step===1"><h2 class="text-xl font-bold">Tell us about yourself</h2><div class="mt-5 grid gap-4 sm:grid-cols-2"><?php foreach([['first_name','First name','text'],['last_name','Last name','text'],['email','Email address','email'],['phone','Phone number','tel'],['city','City','text'],['age','Age','number']] as [$name,$label,$type]): ?><label class="text-sm font-semibold text-slate-700"><?= $label ?><input required type="<?= $type ?>" name="<?= $name ?>" value="<?= esc(old($name)) ?>" class="mt-1.5 w-full rounded-xl border border-slate-200 bg-slate-50 px-4 py-3 text-sm"></label><?php endforeach; ?><label class="sm:col-span-2 text-sm font-semibold">Address<input required name="address" value="<?= esc(old('address')) ?>" class="mt-1.5 w-full rounded-xl border border-slate-200 bg-slate-50 px-4 py-3 text-sm"></label></div></section><section x-cloak x-show="step===2"><h2 class="text-xl font-bold">When can you volunteer?</h2><p class="mt-1 text-sm text-slate-500">Choose all days that generally work for you.</p><div class="mt-5 grid grid-cols-2 gap-3 sm:grid-cols-4"><?php foreach(['Monday','Tuesday','Wednesday','Thursday','Friday','Saturday','Sunday'] as $day): ?><label class="rounded-xl border p-3 text-sm" :class="days.includes('<?= $day ?>')?'border-rescue-500 bg-rescue-50':''"><input class="hidden" type="checkbox" name="available_days[]" value="<?= $day ?>" @change="days.includes('<?= $day ?>')?days=days.filter(d=>d!=='<?= $day ?>'):days.push('<?= $day ?>')"><span><?= substr($day,0,3) ?></span></label><?php endforeach; ?></div><div class="mt-5 grid gap-4 sm:grid-cols-3"><label class="text-sm font-semibold">Preferred time<select required name="time_slot" class="mt-1.5 w-full rounded-xl border p-3"><option value="">Choose</option><option value="morning">Morning</option><option value="afternoon">Afternoon</option><option value="evening">Evening</option><option value="flexible">Flexible</option></select></label><label class="text-sm font-semibold">Hours/week<input name="hours_per_week" placeholder="e.g. 3–5" class="mt-1.5 w-full rounded-xl border p-3"></label><label class="text-sm font-semibold">Start date<input type="date" name="start_date" class="mt-1.5 w-full rounded-xl border p-3"></label></div></section><section x-cloak x-show="step===3"><h2 class="text-xl font-bold">Experience & interests</h2><div class="mt-5"><p class="text-sm font-semibold">Animal experience</p><div class="mt-2 flex gap-4"><?php foreach(['Yes','Some','No'] as $value): ?><label class="text-sm"><input required type="radio" name="has_animal_exp" value="<?= $value ?>"> <?= $value ?></label><?php endforeach; ?></div></div><textarea name="experience_details" class="mt-5 min-h-24 w-full rounded-xl border p-3 text-sm" placeholder="Tell us about your animal-care experience (optional)"></textarea><p class="mt-5 text-sm font-semibold">Roles you are interested in</p><div class="mt-2 grid grid-cols-2 gap-3 sm:grid-cols-3"><?php foreach(['feeding','cleaning','grooming','transport','socialization','medical support'] as $role): ?><label class="rounded-xl border p-3 text-sm"><input type="checkbox" name="roles[]" value="<?= $role ?>"> <?= ucfirst($role) ?></label><?php endforeach; ?></div><textarea required name="motivation" class="mt-5 min-h-28 w-full rounded-xl border p-3 text-sm" placeholder="Why would you like to volunteer?"></textarea></section><section x-cloak x-show="step===4"><h2 class="text-xl font-bold">Emergency contact</h2><p class="mt-1 text-sm text-slate-500">Please provide someone we can reach in an emergency.</p><div class="mt-5 grid gap-4 sm:grid-cols-2"><label class="text-sm font-semibold">Full name<input required name="emergency_name" class="mt-1.5 w-full rounded-xl border p-3"></label><label class="text-sm font-semibold">Relationship<select required name="emergency_relation" class="mt-1.5 w-full rounded-xl border p-3"><option value="">Select relationship</option><option>Parent</option><option>Spouse / Partner</option><option>Sibling</option><option>Friend</option><option>Other</option></select></label><label class="text-sm font-semibold sm:col-span-2">Contact number<input required name="emergency_phone" class="mt-1.5 w-full rounded-xl border p-3"></label></div><label class="mt-6 flex gap-3 rounded-xl border p-4 text-sm text-slate-600"><input required type="checkbox" class="mt-1">I confirm that my information is accurate and I agree to the Volunteer Terms & shelter code of conduct.</label></section></div><footer class="flex items-center justify-between border-t bg-slate-50 px-6 py-4"><button type="button" @click="step=Math.max(1,step-1)" :disabled="step===1" class="rounded-xl border px-4 py-2 text-sm disabled:opacity-30">Previous</button><button type="button" x-show="step<4" @click="step++" class="rounded-xl bg-rescue-600 px-5 py-2.5 text-sm font-semibold text-white">Continue</button><button x-show="step===4" class="rounded-xl bg-adopted-600 px-5 py-2.5 text-sm font-semibold text-white">Submit Application</button></footer></form></main><?php endif; ?><script>lucide.createIcons()</script></body></html>
